import { MeshBasicNodeMaterial, PlaneGeometry, Mesh } from 'three/webgpu';

export default function createNode(config, ctx) {
  // Load texture
  const texture = ctx.textureLoader.load(config.assets.imageUrl);

  // Material using basic node material (TSL-compliant)
  const material = new MeshBasicNodeMaterial({
    map: texture,
    color: 0xffffff,
  });

  // Geometry with aspect ratio from the source rect (512x320)
  const width = 1.6;
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height);

  // Create mesh
  const mesh = new Mesh(geometry, material);

  // Apply scene placement from config
  const { position, rotation, scale } = config.scenePlacement;
  mesh.position.set(position[0], position[1], position[2]);
  mesh.rotation.set(rotation[0], rotation[1], rotation[2]);
  mesh.scale.set(scale[0], scale[1], scale[2]);

  // Handlers (none)
  mesh.userData.handlers = {};

  // Cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return mesh;
}
